#!/usr/bin/env node
import fs from 'node:fs';
const file=process.argv[2]||'factory/task-graph.yml';if(!fs.existsSync(file)){console.error(`missing ${file}`);process.exit(1)}const raw=fs.readFileSync(file,'utf8');let tasks=[];
try{const j=JSON.parse(raw);tasks=Array.isArray(j)?j:(j.tasks||[])}catch{const chunks=raw.split(/\n(?=\s*-?\s*(?:id|ID):\s*F\d+)/);for(const c of chunks){const id=c.match(/(?:^|\n)\s*-?\s*(?:id|ID):\s*['"]?(F\d+)/)?.[1];if(!id)continue;const stack=c.match(/(?:^|\n)\s*stack:\s*['"]?([^\n'"#]+)/)?.[1]?.trim();const ds=c.match(/(?:dependsOn|depends_on|dependencies):\s*\[([^\]]*)\]/)?.[1]?.split(',').map(x=>x.trim().replace(/["']/g,'')).filter(Boolean)||[];tasks.push({id,stack,dependsOn:ds})}}
const e=[],map=new Map();for(const t of tasks){if(!/^F(?:1[0-5]|[0-9])$/.test(t.id))e.push(`invalid id ${t.id}`);if(map.has(t.id))e.push(`duplicate ${t.id}`);map.set(t.id,t)}for(let i=0;i<=15;i++)if(!map.has(`F${i}`))e.push(`missing F${i}`);
for(const t of tasks)for(const d of (t.dependsOn||t.dependencies||[]))if(!map.has(d))e.push(`${t.id} unknown dependency ${d}`);
const visiting=new Set(),done=new Set();function visit(id){if(visiting.has(id)){e.push(`cycle at ${id}`);return}if(done.has(id))return;visiting.add(id);for(const d of(map.get(id)?.dependsOn||map.get(id)?.dependencies||[]))visit(d);visiting.delete(id);done.add(id)}for(const id of map.keys())visit(id);
const expectedStacks={F0:'Contract',F1:'Contract',F2:'API',F3:'API',F4:'API',F5:'Web',F6:'Web',F7:'Search',F8:'Search',F9:'Chat',F10:'Chat',F11:'Preflight',F12:'Infra',F13:'Infra',F14:'Integration',F15:'Release'};for(const [id,s] of Object.entries(expectedStacks))if(map.get(id)?.stack?.toLowerCase()!=s.toLowerCase())e.push(`${id} must be in ${s}`);
const expectedDependencies={F0:[],F1:['F0'],F2:['F1'],F3:['F2'],F4:['F3'],F5:['F1'],F6:['F4','F5'],F7:['F4'],F8:['F6','F7'],F9:['F4'],F10:['F6','F9'],F11:['F8','F10'],F12:['F4','F6','F8','F10'],F13:['F11','F12'],F14:['F8','F10','F13'],F15:['F14']};for(const [id,want] of Object.entries(expectedDependencies)){const got=[...(map.get(id)?.dependsOn||map.get(id)?.dependencies||[])].sort();if(JSON.stringify(got)!==JSON.stringify([...want].sort()))e.push(`${id} dependencies ${got.join(',')||'none'} expected ${want.join(',')||'none'}`)}
if(/contract:\s*aimarket-factory-f0-f15/.test(raw)){const automaticIds=[...raw.matchAll(/(?:^|\n)\s*-?\s*id:\s*['"]?(F\d+)[\s\S]*?(?=(?:\n\s*-?\s*id:\s*['"]?F\d+)|$)/g)].filter(match=>/^\s*automaticDispatch:\s*true\s*$/m.test(match[0])).map(match=>match[1]).sort();const expectedAutomatic=Array.from({length:12},(_,index)=>`F${index+2}`).sort();if(JSON.stringify(automaticIds)!==JSON.stringify(expectedAutomatic))e.push(`automatic dispatch ${automaticIds.join(',')||'none'} expected ${expectedAutomatic.join(',')}`);for(const id of ['F14','F15'])if(!new RegExp(`(?:^|\\n)\\s*-?\\s*id:\\s*['"]?${id}[\\s\\S]*?^\\s*automaticDispatch:\\s*false\\s*$`,'m').test(raw))e.push(`${id} must require explicit gated readiness`);}
if(e.length){console.error(e.join('\n'));process.exit(1)}console.log('PASS task graph F0-F15 acyclic, dependency-exact, stack-aligned, and readiness-gated');
